steps.command:
cat > /tmp/memfd.pl <<'PERLEOF'
use Fcntl;
# memfd_create 는 이름만 있고 디스크에 없는 파일을 만든다. arm64 에서 279 번.
my $name = "pbpf"; my $flags = 0;
my $fd = syscall(279, $name, $flags);
die "memfd_create: $!" if $fd < 0;
open(my $m, '>&=', $fd) or die "fdopen: $!";
select((select($m), $|=1)[0]);
print $m "#!/bin/sh\nid > /dev/null\nexit 7\n";
# 페이로드를 자식이 실행하려면 close-on-exec 를 꺼야 물려받는다.
fcntl($m, F_SETFD, 0) or die "fcntl: $!";
my $rc = system("/proc/self/fd/$fd");
print "memfd payload exit=", $rc >> 8, "\n";
PERLEOF
perl /tmp/memfd.pl
